const fs = require('fs').promises;
const path = require('path');

function get_ls_result(dir_path) {
  // Validate input to prevent path traversal and ensure it's a string
  if (typeof dir_path !== 'string' || dir_path.trim() === '') {
    return Promise.resolve('');
  }

  // Normalize the path to handle relative paths and ensure it's safe
  const resolvedPath = path.resolve(dir_path);
  const safePath = path.normalize(resolvedPath);

  // Check if the path is valid and exists
  return fs.access(safePath, fs.constants.F_OK)
    .then(() => fs.readdir(safePath, { withFileStats: true }))
    .then(entries => {
      const result = [];
      for (const entry of entries) {
        const { name, stats } = entry;
        const permissions = stats.isDirectory() ? 'd' : '-';
        const owner = stats.uid !== undefined ? stats.uid : '-';
        const group = stats.gid !== undefined ? stats.gid : '-';
        const size = stats.size !== undefined ? stats.size : '-';
        const month = stats.mtime.toLocaleString('en-US', { month: 'short' });
        const day = stats.mtime.getDate();
        const year = stats.mtime.getFullYear();
        const time = stats.mtime.toLocaleString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

        result.push(
          `${permissions}${owner}${group}${size} ${month}${day} ${time} ${name}`
        );
      }
      return result.join('\n');
    })
    .catch(() => '');
}
